const listPhotoAlbumMonthBuckets = `-- name: ListPhotoAlbumMonthBuckets :many
WITH f AS (
    SELECT a.taken_local,
           row_number() OVER (PARTITION BY coalesce(a.content_hash, a.id::text) ORDER BY a.id) AS rn
    FROM photo_album_visible_items i JOIN photo_assets a ON a.id = i.asset_id
    WHERE i.album_id = $1 AND a.parent_id IS NULL AND NOT a.hidden AND a.trashed_at IS NULL
)
SELECT date_trunc('month', taken_local)::date AS month, count(*)::bigint AS count
FROM f WHERE rn = 1
GROUP BY 1
ORDER BY 1 DESC
`

type ListPhotoAlbumMonthBucketsRow struct {
	Month pgtype.Date `json:"month"`
	Count int64       `json:"count"`
}

func (q *Queries) ListPhotoAlbumMonthBuckets(ctx context.Context, albumID pgtype.UUID) ([]ListPhotoAlbumMonthBucketsRow, error) {
	rows, err := q.db.Query(ctx, listPhotoAlbumMonthBuckets, albumID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPhotoAlbumMonthBucketsRow{}
	for rows.Next() {
		var i ListPhotoAlbumMonthBucketsRow
		if err := rows.Scan(&i.Month, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPhotoAlbumsFor = `-- name: ListPhotoAlbumsFor :many
WITH mine AS (
    SELECT al.id, al.owner_id, al.name, al.created_at, al.updated_at FROM photo_albums al
    WHERE al.owner_id = $1
       OR EXISTS (SELECT 1 FROM photo_album_members m WHERE m.album_id = al.id AND m.user_id = $1)
), shown AS (
    SELECT i.album_id, a.id, a.taken_at,
           row_number() OVER (PARTITION BY i.album_id, coalesce(a.content_hash, a.id::text) ORDER BY a.id) AS rn
    FROM photo_album_visible_items i JOIN photo_assets a ON a.id = i.asset_id
    WHERE i.album_id IN (SELECT id FROM mine)
      AND a.parent_id IS NULL AND NOT a.hidden AND a.trashed_at IS NULL
)
SELECT m.id, m.owner_id, m.name, m.created_at, m.updated_at, u.email AS owner_email,
       (SELECT count(*) FROM shown s WHERE s.album_id = m.id AND s.rn = 1)::bigint AS count,
       (SELECT s.id FROM shown s WHERE s.album_id = m.id AND s.rn = 1
        ORDER BY s.taken_at DESC, s.id LIMIT 1)::uuid AS cover_id,
       (SELECT count(*) FROM photo_album_members mm WHERE mm.album_id = m.id)::bigint AS members
FROM mine m JOIN users u ON u.id = m.owner_id
ORDER BY m.updated_at DESC, m.id
`

type ListPhotoAlbumsForRow struct {
	ID         pgtype.UUID        `json:"id"`
	OwnerID    pgtype.UUID        `json:"owner_id"`
	Name       string             `json:"name"`
	CreatedAt  pgtype.Timestamptz `json:"created_at"`
	UpdatedAt  pgtype.Timestamptz `json:"updated_at"`
	OwnerEmail string             `json:"owner_email"`
	Count      int64              `json:"count"`
	CoverID    pgtype.UUID        `json:"cover_id"`
	Members    int64              `json:"members"`
}

// The albums a user owns or is a member of, with what they show: visible cards (each
// file once) and the latest of them as the cover.
func (q *Queries) ListPhotoAlbumsFor(ctx context.Context, userID pgtype.UUID) ([]ListPhotoAlbumsForRow, error) {
	rows, err := q.db.Query(ctx, listPhotoAlbumsFor, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPhotoAlbumsForRow{}
	for rows.Next() {
		var i ListPhotoAlbumsForRow
		if err := rows.Scan(
			&i.ID,
			&i.OwnerID,
			&i.Name,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.OwnerEmail,
			&i.Count,
			&i.CoverID,
			&i.Members,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

