const removePhotoAlbumItems = `-- name: RemovePhotoAlbumItems :execrows
DELETE FROM photo_album_items
WHERE album_id = $1 AND asset_id = ANY($2::uuid[])
  AND ($3::bool OR added_by = $4)
`

type RemovePhotoAlbumItemsParams struct {
	AlbumID  pgtype.UUID   `json:"album_id"`
	AssetIds []pgtype.UUID `json:"asset_ids"`
	AnyItem  bool          `json:"any_item"`
	UserID   pgtype.UUID   `json:"user_id"`
}

// The owner takes out anything; a member what they added.
func (q *Queries) RemovePhotoAlbumItems(ctx context.Context, arg RemovePhotoAlbumItemsParams) (int64, error) {
	result, err := q.db.Exec(ctx, removePhotoAlbumItems,
		arg.AlbumID,
		arg.AssetIds,
		arg.AnyItem,
		arg.UserID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

